<script setup lang="ts">
import{computed,ref,watch}from'vue';
import{parityMessages}from'./parity-labels';
import type{Language}from'./types';
const props=defineProps<{language:Language;commands:{id:string;zh:string;en:string;shortcut?:string;enabled:boolean}[]}>();
const emit=defineEmits(['close','run']),query=ref(''),active=ref(0),t=computed(()=>parityMessages[props.language]);
const results=computed(()=>{const tokens=query.value.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);return props.commands.filter(command=>tokens.every(token=>[command.zh,command.en,command.shortcut??''].join(' ').toLocaleLowerCase().includes(token))).slice(0,100);});
watch(query,()=>{active.value=Math.max(0,results.value.findIndex(command=>command.enabled));});
function run(){const command=results.value[active.value];if(command?.enabled)emit('run',command.id);}
function key(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='Escape'){event.preventDefault();event.stopPropagation();emit('close');return;}if(event.key==='Enter'){event.preventDefault();run();}if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const enabled=results.value.map((command,index)=>command.enabled?index:-1).filter(index=>index>=0);if(!enabled.length)return;const index=enabled.indexOf(active.value),direction=event.key==='ArrowUp'?-1:1;active.value=enabled[event.key==='Home'?0:event.key==='End'?enabled.length-1:(index+direction+enabled.length)%enabled.length];document.getElementById('command-'+active.value)?.scrollIntoView({block:'nearest'});}}
</script>
<template><div class="modal-shade" @click.self="emit('close')"><section class="dialog command-dialog" role="dialog" aria-modal="true" :aria-label="t.commandFinder" @keydown="key"><h2>{{t.commandFinder}}</h2><input v-model="query" data-testid="command-search" :aria-label="t.searchCommands" role="combobox" aria-autocomplete="list" aria-expanded="true" aria-controls="command-results" :aria-activedescendant="results.length?'command-'+active:undefined" :placeholder="t.searchCommands"><ul id="command-results" role="listbox" :aria-label="t.commandFinder"><li v-for="(command,index) in results" :key="command.id"><button :id="'command-'+index" role="option" :aria-selected="active===index" :disabled="!command.enabled" tabindex="-1" :data-command="command.id" @pointermove="active=index" @click="emit('run',command.id)"><span>{{language==='en'?command.en:command.zh}}</span><kbd v-if="command.shortcut">{{command.shortcut}}</kbd></button></li></ul><p v-if="!results.length">{{t.noCommands}}</p><button @click="emit('close')">{{t.close}}</button></section></div></template>
<style scoped>.command-dialog{width:min(640px,94vw);max-height:85vh}.command-dialog>input{width:100%;margin-bottom:12px}.command-dialog ul{list-style:none;max-height:52vh;overflow:auto;padding:0;margin:0 0 12px}.command-dialog li button{display:flex;justify-content:space-between;gap:16px;width:100%;text-align:left;border:0;border-radius:3px}.command-dialog li button[aria-selected=true]{background:var(--accent);color:#10291e}.command-dialog kbd{opacity:.7;white-space:nowrap}</style>
